#!/usr/bin/env bun
/**
 * SQL migration runner
 * ============================================================================
 *
 * WHY IT EXISTS
 *
 * There were 31 migration files and NOTHING applied them. `db:migrate` was
 * `drizzle-kit migrate`, whose journal has 2 entries; the other 29 lived in
 * `src/db/migrations/` and only `pg-mem` read them for the tests. That is: the
 * real schema was maintained by hand with `psql`, and CI tested against an
 * imaginary schema.
 *
 * ORDER
 *
 *   1. drizzle/*.sql            — the base schema generated by drizzle-kit
 *   2. src/db/migrations/*.sql  — the manual ones, which assume that base
 *
 * It is the same order `pg-mem-db.ts` already used, and it is not arbitrary: the
 * manual ones start at 0002 because they extend what 0000 and 0001 create.
 *
 * WHAT MATTERS FOR A DATABASE THAT ALREADY EXISTS
 *
 * Existing production databases ALREADY have these migrations applied by hand. Running
 * the runner on them would try to reapply them. That is what `--baseline` is for:
 * it marks everything present as applied WITHOUT running it. It is the first command
 * to run on a preexisting database, and only once.
 *
 * USAGE
 *   bun run scripts/migrate.ts --status     see applied and pending
 *   bun run scripts/migrate.ts --prune      delete history whose file no longer exists
 *   bun run scripts/migrate.ts --baseline   existing database: mark without running
 *   bun run scripts/migrate.ts --dry-run    what would run
 *   bun run scripts/migrate.ts              apply pending + RLS
 *   bun run scripts/migrate.ts --no-rls     apply migrations only
 *   bun run scripts/migrate.ts --kon kon-blog  also, those of that installed kon
 *                                           even if it is not active (used by
 *                                           `kitsuden kon add`)
 *   bun run scripts/migrate.ts --all-kons
 *                                           ALL kons, not only the
 *                                           enabled ones. For CI: it validates
 *                                           chains that on a server would not
 *                                           be applied until someone
 *                                           activates that kon.
 */

import "./lib/real-postgres-only";

import { createHash } from "node:crypto";
import { existsSync, readdirSync } from "node:fs";
import { createRequire } from "node:module";
import { basename, dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

import { sql } from "drizzle-orm";

import { db } from "../src/db";
import { konIdOf, installedKon, listInstalledKons } from "../src/lib/installed-kons";
import { adoptRenamed, hadChecksum } from "../src/lib/migration-history";
import { readSqlFile, type SqlFile } from "../src/lib/sql-file";

import { detailError } from "./lib/db-error";
import { applyRlsPolicies, checkSuperuser, reportRls, verifyRls } from "./lib/rls";

const here = dirname(fileURLToPath(import.meta.url));

/** Advisory lock key. Fixed constant: it cannot change between versions. */
const LOCK_KEY = 8_913_442_071_004_501n;

const SOURCES = [
  { source: "drizzle", dir: resolve(here, "../drizzle") },
  { source: "migrations", dir: resolve(here, "../src/db/migrations") },
];

/**
 * Migrations of the `packages/core` packages.
 *
 * Same problem as with the kons and the same solution: `packages/core/*​/migrations`
 * has 5 .sql files that nobody ran. The visible symptom was
 *
 *     Calculated fields table not found. Run migration: 0001_calculated_fields.sql
 *
 * a warning asking to run by hand a file that DOES exist —in
 * `packages/core/datasets/migrations/`— but that the runner did not look at.
 *
 * Unlike the kons, core always runs: it is not optional nor does it depend on
 * the configuration.
 *
 * ── THE EXCLUSION ──────────────────────────────────────────────────────────
 *
 * `vector-search` is left out on purpose. Its only file,
 * `001_migrate_from_ai_memories.sql`, is a DATA migration from an old
 * version: it inserts into `vector_index` and `vector_chunks` reading from `ai_memories`.
 * None of those three tables exists in the current schema —the vector now lives in
 * `vector_documents`— so applying it fails on the first statement.
 *
 * Also its prefix is 3 digits, which the ordering rule further down
 * rejects. The file is kept as a record of that change; it is not run.
 */
const CORE_EXCLUDED = new Set(["vector-search"]);

function coreSources(): { source: string; dir: string }[] {
  const base = join(ROOT, "packages", "core");
  if (!existsSync(base)) return [];

  const sources: { source: string; dir: string }[] = [];
  for (const pkg of readdirSync(base).sort()) {
    if (CORE_EXCLUDED.has(pkg)) continue;
    const dir = join(base, pkg, "migrations");
    if (existsSync(dir)) sources.push({ source: `core-${pkg}`, dir });
  }
  return sources;
}

/** Monorepo root: `apps/api/scripts` -> two levels above `apps/api`. */
const ROOT = resolve(here, "../../..");

/**
 * Migrations of the enabled kons.
 *
 * ── WHY THIS DID NOT EXIST AND WHY IT IS NEEDED ────────────────────────────
 *
 * 24 kons ship migrations —45 .sql files in total— and NOBODY ran them.
 * The runner only looked at `drizzle/` and `src/db/migrations/`.
 *
 * Instead, each kon created its tables at startup, with a
 * `CREATE TABLE IF NOT EXISTS` from the service itself. That had three
 * problems, and the third made it impossible:
 *
 *   1. Unversioned: no checksum, no order, no way to know what was applied.
 *   2. It failed silently. A `console.warn` among hundreds of startup lines
 *      stops nobody, so a kon with no tables looked healthy.
 *   3. Since the API connects with an unprivileged role —so that RLS is
 *      actually applied— that role does NOT have CREATE on the schema. Hot creation
 *      can no longer work, and rightly so: creating tables
 *      is a migration's job.
 *
 * The measured result: of the 5 installed kons, 4 had NONE of their
 * tables. `kon-crm` declared 9 and all 9 were missing.
 *
 * ── WHICH KONS ─────────────────────────────────────────────────────────────
 *
 * Those the configuration declares enabled, not those in `installed_kons`: on
 * a clean startup that table is empty when we migrate, because the kons are
 * registered AFTER. Looking at the configuration is the only thing that works the first
 * time, which is exactly when it matters.
 *
 * They go after the core ones on purpose: the kons' tables reference
 * `auth_users` and the like.
 */
async function konSources(all?: boolean): Promise<{ source: string; dir: string }[]> {
  // ── --all-kons ──────────────────────────────────────────────────────
  //
  // Applies the chain of ALL the repo's kons, enabled or not.
  //
  // It exists for CI, and it is the answer to how migration chains
  // that did not apply slipped into production. The broken kons that were found —dms with no
  // startup migration, esports and games with `ALTER TYPE IF EXISTS` (syntax
  // that does not exist), booking renaming a table to its own name— were
  // ALL off by default.
  //
  // That is: CI migrated the six enabled kons, came out green, and the chain
  // of the other twenty-odd was run by nobody until a user
  // activated one from the panel. At that moment, and only then, it
  // was discovered that the SQL did not even parse.
  //
  // It is NOT used on a server: it would apply tables for kons nobody asked for.
  // `--todos-los-kons` is the flag's earlier spelling, kept as an alias.
  if (all ?? (process.argv.includes("--all-kons") || process.argv.includes("--todos-los-kons"))) {
    return allKons();
  }

  let enabled: string[] = [];
  try {
    const config = await import(resolve(here, "../kitsuden.config.ts"));
    const staticConfig = config.staticConfig ?? config.default ?? config;
    enabled = staticConfig.kons ?? staticConfig.modules ?? [];
  } catch (err) {
    // Without configuration nothing is invented: a warning is shown and the core continues.
    console.warn(
      `  ⚠  Could not read kitsuden.config.ts (${err instanceof Error ? err.message : err}).
` + `     No kon migrations will be applied.`
    );
    return [];
  }

  // And those the PANEL has activated. Without this, activating a kon from the admin and
  // rebuilding the container sent the kon back to "enabled with no tables": the
  // config file said `enabled: false` and the runner skipped it,
  // while the `modules` table said the opposite.
  //
  // Two sources of truth for "which kons exist" is the underlying problem; as long as
  // both exist, migrating the UNION is the only thing that breaks nobody: applying
  // one migration too many costs an idempotent CREATE TABLE, and applying one
  // too few costs a broken screen.
  for (const id of await activatedKonsInDatabase()) {
    if (!enabled.includes(id)) enabled.push(id);
  }

  // `--kon <id>` (repeatable): used by `kitsuden kon add` to migrate the kon it
  // has just installed even if it is not yet active in the database.
  for (const id of konsRequestedByArgument()) {
    if (!enabled.includes(id)) enabled.push(id);
  }

  // Only what is INSTALLED: a kon active in the database that is no longer installed has no
  // files to apply (and a warning is shown, instead of skipping it silently).
  const sources: { source: string; dir: string }[] = [];
  const seen = new Set<string>();
  for (const id of enabled) {
    const kon = installedKon(id);
    if (kon?.source === "core") continue; // they go through coreSources()
    if (!kon?.path) {
      console.warn(
        `  ⚠  ${konIdOf(id)} is active but not installed: not migrated (kitsuden kon add ${konIdOf(id).replace(/^kon-/, "")})`
      );
      continue;
    }
    if (seen.has(kon.id)) continue;
    seen.add(kon.id);
    const source = konSource(kon.path);
    if (source) sources.push(source);
  }
  return sources;
}

/**
 * The migration source of an installed kon. The name in the history is
 * `<folder>/<file>`, with the kon's REAL folder (`kon-blog`), same as
 * when the kons lived in packages/kons: so a database that is already migrated recognizes
 * what was applied even though the kon now comes from elsewhere.
 */
function konSource(route: string): { source: string; dir: string } | null {
  const dir = join(route, "migrations");
  return existsSync(dir) ? { source: basename(route), dir } : null;
}

/** The ids passed with `--kon <id>` (or `--kon=<id>`). */
function konsRequestedByArgument(): string[] {
  const output: string[] = [];
  const args = process.argv.slice(2);
  for (let i = 0; i < args.length; i++) {
    if (args[i] === "--kon" && args[i + 1]) output.push(konIdOf(args[++i]));
    else if (args[i].startsWith("--kon=")) output.push(konIdOf(args[i].slice(6)));
  }
  return output;
}

/**
 * Kons marked as active in the `modules` table.
 *
 * It may not exist yet —first startup, before the first migration— and
 * that is NOT an error: an empty list is returned and the configuration decides.
 */
async function activatedKonsInDatabase(): Promise<string[]> {
  try {
    const res = await db.execute(sql.raw(`SELECT key FROM modules WHERE enabled = true`));
    const rows =
      (res as unknown as { rows?: { key: string }[] }).rows ??
      (res as unknown as { key: string }[]);
    return (rows ?? []).map((f) => f.key);
  } catch {
    return [];
  }
}

/**
 * All INSTALLED kons that ship migrations (`--all-kons`).
 *
 * It used to be all those in the repository's `packages/kons` folder; since
 * the kons live in kitsuden-kons, they are the ones declared in the installation
 * (`kitsuden.kons.json` + `KITSUDEN_KONS`). For the kons' CI, all of them
 * are declared.
 *
 * The order between kons is alphabetical by folder. A kon whose chain depends on
 * ANOTHER kon's is a coupling that this runner cannot resolve, and that
 * should not exist: a kon declares its own tables.
 */
function allKons(): { source: string; dir: string }[] {
  const sources: { source: string; dir: string }[] = [];
  for (const kon of listInstalledKons()) {
    if (kon.source === "core" || !kon.path) continue;
    const source = konSource(kon.path);
    if (source) sources.push(source);
  }
  return sources.sort((a, b) => a.source.localeCompare(b.source));
}

/**
 * Core agent functions (`kitsuden_effective_admin`, …) that the
 * kons' migrations may use in their policies. Idempotent: applied
 * BEFORE the pending migrations (and again with the RLS). See the file.
 */
const AGENT_FUNCTIONS = resolve(here, "../src/db/agent-functions.sql");

/** RLS: applied AFTER the migrations and idempotent by design. */
const RLS_FILES = [
  AGENT_FUNCTIONS,
  resolve(here, "../src/db/rls-policies.sql"),
  resolve(here, "../src/db/rls-owned-tables.sql"),
  // Core: secrets, credentials, audit and auth_users
  resolve(here, "../src/db/rls-system-only.sql"),
];

// ── Discovery ───────────────────────────────────────────────────────────────

async function discover(all?: boolean): Promise<SqlFile[]> {
  const files: SqlFile[] = [];

  for (const { source, dir } of [...SOURCES, ...coreSources(), ...(await konSources(all))]) {
    if (!existsSync(dir)) continue;
    const sqls = readdirSync(dir)
      .filter((f) => f.endsWith(".sql"))
      // Lexicographic order over names with a 4-digit numeric prefix.
      // It is stable as long as the prefix is kept; a file with no prefix would
      // sort last, which is why it is rejected further down.
      .sort();

    for (const f of sqls) {
      files.push(readSqlFile(join(dir, f), `${source}/${f}`));
    }
  }

  const withoutPrefix = files.filter((f) => !/\/\d{4}_/.test(f.name));
  if (withoutPrefix.length > 0) {
    // Without a prefix there is no deterministic order, and order is the only thing that
    // makes a chain of migrations reproducible.
    throw new Error(
      `Migrations without a 4-digit numeric prefix (the order would be arbitrary):\n` +
        withoutPrefix.map((f) => `  ${f.name}`).join("\n")
    );
  }

  return files;
}

// ── Extension pre-check ─────────────────────────────────────────────────────

/**
 * Verifies that the extensions the chain asks for exist on the server BEFORE
 * applying anything.
 *
 * Without this, a missing extension goes unnoticed until the statement that uses its
 * type: the chain applies six migrations, blows up halfway through the seventh with
 * `type "vector" does not exist`, and you have to deduce that the problem was on
 * the server and not in the SQL. Checking beforehand turns half an hour into a
 * message.
 *
 * `CREATE EXTENSION IF NOT EXISTS` does not protect: it does not fail if the extension is not
 * AVAILABLE, only if it is already created.
 */
async function checkExtensions(files: SqlFile[]): Promise<void> {
  const requestedOnes = new Set<string>();
  for (const f of files) {
    for (const m of f.raw.matchAll(/CREATE EXTENSION\s+(?:IF NOT EXISTS\s+)?"?([a-z_]+)"?/gi)) {
      requestedOnes.add(m[1].toLowerCase());
    }
  }
  if (requestedOnes.size === 0) return;

  let availableItems: Set<string>;
  try {
    const res = await db.execute(sql.raw(`SELECT name FROM pg_available_extensions`));
    const rows = (Array.isArray(res) ? res : ((res as { rows?: unknown[] }).rows ?? [])) as Array<{
      name: string;
    }>;
    availableItems = new Set(rows.map((r) => r.name.toLowerCase()));
  } catch {
    // If the catalog is not readable, it cannot be checked: carry on and let
    // the migration fail with its own error.
    return;
  }

  const areMissing = [...requestedOnes].filter((e) => !availableItems.has(e));
  if (areMissing.length > 0) {
    throw new Error(
      `Postgres extensions the chain needs are missing: ${areMissing.join(", ")}\n\n` +
        `    In Docker, use an image that includes them — for pgvector:\n` +
        `      image: pgvector/pgvector:pg16\n\n` +
        `    In lite mode (PGlite) 'vector' is NOT available: the functions of\n` +
        `    brain and semantic search cannot be migrated there.`
    );
  }
}

// ── History ─────────────────────────────────────────────────────────────────

async function createHistoryTable() {
  await db.execute(
    sql.raw(`
      CREATE TABLE IF NOT EXISTS kitsuden_migrations (
        name        TEXT PRIMARY KEY,
        checksum    TEXT NOT NULL,
        applied_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
        duration_ms INTEGER,
        baselined   BOOLEAN NOT NULL DEFAULT false
      )
    `)
  );
}

interface Applied {
  name: string;
  checksum: string;
  baselined: boolean;
}

const CHECKSUMS_V0: Record<string, string[]> = createRequire(import.meta.url)(
  "./migration-checksums-v0.json"
);

async function readApplied(): Promise<Map<string, Applied>> {
  const res = await db.execute(
    sql.raw(`SELECT name, checksum, baselined FROM kitsuden_migrations`)
  );
  const rows = (res as unknown as { rows?: Applied[] }).rows ?? (res as unknown as Applied[]);
  return new Map((rows ?? []).map((r) => [r.name, r]));
}

/**
 * Does the history checksum correspond to this file?
 *
 * It is also compared against the file in LF and in CRLF, because the same commit
 * has produced different bytes depending on where it was checked out: before
 * `.gitattributes` said `eol=lf`, on Windows (autocrlf) many migrations arrived with
 * CRLF and in a Linux clone with LF. A database migrated from Windows keeps
 * checksums of CRLF files in its history (41 of 110 are). Comparing
 * only the bytes, the first startup on a Linux server with that database
 * restored would stop with «changed AFTER being applied» though nobody has
 * touched a line.
 *
 * A line ending does not change the SQL that runs; any other change does
 * still count as drift.
 */
function sameContent(registeredValue: string, f: SqlFile): boolean {
  if (registeredValue === f.checksum) return true;
  // Migrations whose comments were translated still match the checksum recorded before that.
  if (CHECKSUMS_V0[basename(f.name)]?.includes(registeredValue)) return true;
  // The same, declared by the folder itself (`history.json`, see src/lib/migration-history.ts).
  if (hadChecksum(f, registeredValue)) return true;
  const lf = f.raw.replace(/\r\n/g, "\n");
  const fingerprint = (s: string) => createHash("sha256").update(s).digest("hex").slice(0, 16);
  return (
    registeredValue === fingerprint(lf) ||
    registeredValue === fingerprint(lf.replace(/\n/g, "\r\n"))
  );
}

// ── Execution ───────────────────────────────────────────────────────────────

async function apply(f: SqlFile): Promise<number> {
  const t0 = Date.now();

  // One file = one transaction. If a statement fails, the whole migration
  // is rolled back and the history does not record it: no half migrations remain.
  await db.transaction(async (tx) => {
    for (const [i, stmt] of f.statements.entries()) {
      try {
        await tx.execute(sql.raw(stmt));
      } catch (e) {
        const line = stmt.split("\n")[0].slice(0, 90);
        throw new Error(
          `${f.name} failed at statement ${i + 1}/${f.statements.length}\n` +
            `  ${line}…\n  ${detailError(e)}`
        );
      }
    }
  });

  const ms = Date.now() - t0;
  await db.execute(
    sql.raw(
      `INSERT INTO kitsuden_migrations (name, checksum, duration_ms)
       VALUES ('${f.name}', '${f.checksum}', ${ms})
       ON CONFLICT (name) DO UPDATE SET checksum = EXCLUDED.checksum`
    )
  );
  return ms;
}

// ── Commands ────────────────────────────────────────────────────────────────

async function withLock<T>(fn: () => Promise<T>): Promise<T> {
  let taken = false;
  try {
    await db.execute(sql.raw(`SELECT pg_advisory_lock(${LOCK_KEY})`));
    taken = true;
  } catch {
    // PGlite is single-connection; without locks there is no race to avoid.
  }
  try {
    return await fn();
  } finally {
    if (taken) {
      try {
        await db.execute(sql.raw(`SELECT pg_advisory_unlock(${LOCK_KEY})`));
      } catch {
        /* the connection is closed anyway */
      }
    }
  }
}

async function main() {
  const args = new Set(process.argv.slice(2));
  const dryRun = args.has("--dry-run");
  const baseline = args.has("--baseline");
  const status = args.has("--status");
  const withoutRls = args.has("--no-rls");
  const allowDrift = args.has("--allow-drift");

  const files = await discover();
  await createHistoryTable();
  const applied = await readApplied();

  // Files renamed after being applied (declared in their folder's `history.json`) keep their
  // place in the history instead of running again. `--status` and `--dry-run` only look.
  const looksOnly = status || dryRun;
  const adopted = await adoptRenamed(files, applied, (q) =>
    looksOnly ? Promise.resolve() : db.execute(q)
  );
  for (const a of adopted) console.log(`  renamed  ${a}`);

  // Only when something is going to be run: `--status` and `--baseline` have to
  // work on a server that is missing an extension.
  if (!status && !baseline && !dryRun) {
    await checkExtensions(files.filter((f) => !applied.has(f.name)));
  }

  const pendingItems = files.filter((f) => !applied.has(f.name));
  const derivedMany = files.filter((f) => {
    const a = applied.get(f.name);
    return a && !a.baselined && !sameContent(a.checksum, f);
  });

  /**
   * History entries that no longer have a file.
   *
   * Without this, "69 on disk, 79 applied" looks like corruption and almost never is:
   * `discover()` only looks at ENABLED kons, so the migrations of an
   * off kon are applied and do not show up in the count.
   *
   * Distinguishing it matters because the two cases call for opposite things: that of an off
   * kon must be LEFT —deleting it would make its migrations reapply
   * the day it is turned on, against tables that already exist— and that of a kon
   * truly deleted is surplus. That is why EVERYTHING is discovered in order to decide.
   */
  const onDisk = new Set(
    (args.has("--all-kons") || args.has("--todos-los-kons") ? files : await discover(true)).map(
      (f) => f.name
    )
  );
  const orphans = [...applied.keys()].filter((n) => !onDisk.has(n));
  const ofDisabledKons = applied.size - files.filter((f) => applied.has(f.name)).length;

  if (status) {
    console.log(`\nMigrations: ${files.length} on disk, ${applied.size} applied\n`);
    for (const f of files) {
      const a = applied.get(f.name);
      const mark = !a ? "PENDING" : a.baselined ? "baseline " : "applied ";
      console.log(`  ${mark}  ${f.name}`);
    }
    const off = ofDisabledKons - orphans.length;
    if (off > 0) {
      console.log(
        `\n  ${off} applied migration(s) belong to kons that are not enabled and are not listed.` +
          `\n     To see them: --all-kons`
      );
    }
    if (orphans.length > 0) {
      // Today it breaks nothing: it is history of something that was deleted. The risk comes if
      // a file comes back with THAT name and different content — the runner would take it
      // as applied and never run it.
      console.log(`\n  ⚠  ${orphans.length} applied migration(s) with no file anywhere:`);
      for (const n of orphans) console.log(`       ${n}`);
      console.log(`     If that kon was really deleted, clean them up with --prune.`);
    }
    if (derivedMany.length > 0) {
      console.log(`\n  ⚠  ${derivedMany.length} migration(s) changed after being applied.`);
    }
    return;
  }

  if (args.has("--prune")) {
    if (orphans.length === 0) {
      console.log("Nothing to clean: every history entry has its file.");
      return;
    }
    console.log(`\nDeleting ${orphans.length} history entry(ies) with no file:\n`);
    for (const n of orphans) {
      console.log(`  ${n}`);
      await db.execute(sql`DELETE FROM kitsuden_migrations WHERE name = ${n}`);
    }
    console.log(
      `\nDone. If any of those files comes back, it will be applied again — which is\n` +
        `only correct if its tables are not there either.`
    );
    return;
  }

  if (derivedMany.length > 0 && !allowDrift) {
    // An already-applied migration that changes content means the database
    // and the repo say different things. Editing it does not reapply anything: you have to
    // add a new one. Failing here is cheaper than discovering it in production.
    console.error(
      `\n  ✗ These migrations changed AFTER being applied:\n` +
        derivedMany.map((f) => `      ${f.name}`).join("\n") +
        `\n\n    An applied migration is history: editing it does not reapply it.\n` +
        `    Add a new migration, or use --allow-drift if you know what you are doing.\n`
    );
    process.exit(1);
  }

  if (baseline) {
    if (pendingItems.length === 0) {
      console.log("Nothing to mark: the history is already up to date.");
      return;
    }
    console.log(`\nMarking ${pendingItems.length} migration(s) as applied WITHOUT running them.`);
    console.log("Use it only on a database that ALREADY has this schema.\n");
    for (const f of pendingItems) {
      await db.execute(
        sql.raw(
          `INSERT INTO kitsuden_migrations (name, checksum, baselined)
           VALUES ('${f.name}', '${f.checksum}', true)
           ON CONFLICT (name) DO NOTHING`
        )
      );
      console.log(`  baseline  ${f.name}`);
    }
    return;
  }

  if (pendingItems.length === 0) {
    console.log(`Schema up to date (${applied.size} migrations).`);
  } else if (dryRun) {
    console.log(`\n${pendingItems.length} pending migration(s):\n`);
    for (const f of pendingItems) {
      console.log(`  ${f.name}  (${f.statements.length} statements)`);
    }
    return;
  } else {
    console.log(`\nApplying ${pendingItems.length} migration(s):\n`);
    await applyRlsPolicies([AGENT_FUNCTIONS]);
    for (const f of pendingItems) {
      const ms = await apply(f);
      console.log(`  ok  ${f.name}  (${f.statements.length} statements, ${ms}ms)`);
    }
  }

  if (!withoutRls) {
    if (dryRun) {
      console.log("\n  (--dry-run: RLS not applied)");
    } else {
      console.log("\nApplying RLS policies:");
      await applyRlsPolicies(RLS_FILES);
      reportRls(await verifyRls(), await checkSuperuser());
    }
  }
}

await withLock(main).catch((e) => {
  console.error(`\n  ✗ ${(e as Error).message}\n`);
  process.exit(1);
});

process.exit(0);
